I'm assuming Node/Express with Stripe, since "next required action" maps onto a PaymentIntent's `next_action`. If you use a different provider or stack, the structure carries over, but the field names will change.

```js
// routes/payments.js
import express from "express";
import Stripe from "stripe";

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

// Replace with your real auth and ownership lookup
async function userOwnsPayment(userId, paymentIntentId) {
  const order = await db.orders.findOne({ paymentIntentId, userId });
  return Boolean(order);
}

/**
 * GET /api/payments/:id/next-action
 * Returns a minimal, client-safe description of what the frontend should do next.
 */
router.get("/payments/:id/next-action", requireAuth, async (req, res) => {
  const { id } = req.params;

  if (!id.startsWith("pi_")) {
    return res.status(400).json({ error: "invalid_payment_id" });
  }

  try {
    if (!(await userOwnsPayment(req.user.id, id))) {
      // 404 rather than 403 so we don't confirm the ID exists
      return res.status(404).json({ error: "not_found" });
    }

    const pi = await stripe.paymentIntents.retrieve(id);
    res.set("Cache-Control", "no-store");
    return res.json(toClientAction(pi));
  } catch (err) {
    if (err.type === "StripeInvalidRequestError" && err.code === "resource_missing") {
      return res.status(404).json({ error: "not_found" });
    }
    console.error("next-action error", { id, message: err.message });
    return res.status(500).json({ error: "internal_error" });
  }
});

function toClientAction(pi) {
  switch (pi.status) {
    case "requires_action": {
      const type = pi.next_action?.type;

      if (type === "use_stripe_sdk") {
        // The 3DS challenge. Stripe.js opens the bank's modal given the client secret.
        return {
          status: pi.status,
          action: "handle_3ds",
          clientSecret: pi.client_secret,
        };
      }
      if (type === "redirect_to_url") {
        return {
          status: pi.status,
          action: "redirect",
          url: pi.next_action.redirect_to_url.url,
        };
      }
      return { status: pi.status, action: "unsupported", detail: type ?? null };
    }

    case "requires_confirmation":
      return { status: pi.status, action: "confirm", clientSecret: pi.client_secret };

    case "requires_payment_method":
      // Fresh intent, or the previous attempt (e.g. failed 3DS) was declined
      return {
        status: pi.status,
        action: "retry_with_new_payment_method",
        error: pi.last_payment_error
          ? { code: pi.last_payment_error.code, message: pi.last_payment_error.message }
          : null,
      };

    case "processing":
      return { status: pi.status, action: "wait" };

    case "succeeded":
    case "requires_capture":
      return { status: pi.status, action: "none" };

    case "canceled":
      return { status: pi.status, action: "canceled" };

    default:
      return { status: pi.status, action: "unsupported" };
  }
}

export default router;
```

**Design notes**

- **Minimal response:** The client secret is only returned when the frontend needs it (`requires_action` or `requires_confirmation`). The raw PaymentIntent never goes to the browser.
- **Ownership check:** Without it, anyone who guesses or obtains a PaymentIntent ID could fetch its client secret. Wire `userOwnsPayment` to however you link payments to users or orders.
- **`requires_payment_method` after a challenge:** This is what you'll see if the customer fails or abandons the 3DS challenge. The frontend should show a specific message and let them retry, not the generic error you have today.
- **Webhooks:** Treat this endpoint as a UI helper only. Fulfill orders from the `payment_intent.succeeded` webhook, because users can close the modal or the tab mid-challenge.

**Frontend flow**

1. Call `stripe.handleNextAction({ clientSecret })` when `action === "handle_3ds"`. This opens the bank's challenge in a modal for you, so you don't build the modal yourself.
2. Re-fetch this endpoint, or inspect the result of `handleNextAction`, to decide whether to show success, an error, or a retry.

If you confirm on the client with `stripe.confirmCardPayment(clientSecret)`, Stripe.js handles 3DS automatically. If you confirm server-side, make sure you pass a `return_url` and return the `requires_action` state to the client instead of treating it as a failure. That is a common cause of the symptom you're seeing.

