I'm assuming Stripe PaymentIntents with Node/Express, since you didn't name a provider. If you use Adyen, Braintree, or something else, the shape stays the same but the field names change.

```js
// routes/payments.js
import express from "express";
import Stripe from "stripe";
import { requireAuth } from "../middleware/auth.js";
import { getOrderByPaymentIntentId } from "../db/orders.js";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
const router = express.Router();

// Map Stripe decline codes to messages the UI can show (replaces the generic error)
const DECLINE_MESSAGES = {
  insufficient_funds: "Your card has insufficient funds.",
  expired_card: "Your card has expired.",
  incorrect_cvc: "The security code (CVC) is incorrect.",
  authentication_required: "Your bank requires authentication. Please try again.",
  card_declined: "Your card was declined. Try another card or contact your bank.",
  processing_error: "A processing error occurred. Please try again.",
};

router.get("/api/payments/:paymentIntentId/next-action", requireAuth, async (req, res) => {
  try {
    const { paymentIntentId } = req.params;

    // Authorization: make sure this payment belongs to the current user
    const order = await getOrderByPaymentIntentId(paymentIntentId);
    if (!order || order.userId !== req.user.id) {
      return res.status(404).json({ error: "not_found" });
    }

    const pi = await stripe.paymentIntents.retrieve(paymentIntentId);

    switch (pi.status) {
      case "requires_action": {
        const type = pi.next_action?.type;

        // 3DS challenge. Client passes clientSecret to stripe.handleNextAction(),
        // which opens the bank challenge in a modal.
        if (type === "use_stripe_sdk" || type === "redirect_to_url") {
          return res.json({
            status: "requires_action",
            action: { type: "three_d_secure", clientSecret: pi.client_secret },
          });
        }
        return res.status(422).json({
          status: "requires_action",
          error: "unsupported_next_action",
          actionType: type,
        });
      }

      case "requires_payment_method": {
        // Either a fresh intent, or the last attempt failed/was declined
        const err = pi.last_payment_error;
        if (err) {
          const code = err.decline_code || err.code;
          return res.json({
            status: "failed",
            action: { type: "retry_with_new_payment_method" },
            error: {
              code,
              message: DECLINE_MESSAGES[code] || "Your payment could not be completed.",
            },
          });
        }
        return res.json({ status: "requires_payment_method", action: { type: "collect_payment_method" } });
      }

      case "requires_confirmation":
        return res.json({ status: pi.status, action: { type: "confirm" } });

      case "processing":
        return res.json({ status: "processing", action: { type: "wait" } });

      case "succeeded":
      case "requires_capture":
        return res.json({ status: pi.status, action: { type: "none" } });

      case "canceled":
        return res.json({ status: "canceled", action: { type: "restart_checkout" } });

      default:
        return res.status(500).json({ error: "unknown_status", status: pi.status });
    }
  } catch (e) {
    console.error("next-action error", { id: req.params.paymentIntentId, message: e.message });
    return res.status(500).json({ error: "server_error" });
  }
});

export default router;
```

Notes:

- **Only return `client_secret` when it's needed.** It's returned just for `requires_action`, and only after the ownership check.
- **Don't treat the client as the source of truth for success.** Fulfill orders from the `payment_intent.succeeded` webhook, because users close modals and lose connections mid-challenge.
- **Client side:** after `requires_action`, call `stripe.handleNextAction({ clientSecret })`, then re-poll this endpoint (or wait for your webhook) for the final state. If you use `confirmCardPayment` client-side, Stripe.js handles 3DS automatically. This endpoint then matters mostly for server-side confirmation and for resuming interrupted checkouts.
- **Logging the decline codes** (`last_payment_error.code` / `decline_code`) will show how much of your 3% is actually `authentication_required` versus ordinary declines like insufficient funds. That tells you how much 3DS will recover, and the mapped error messages help in either case.

