Here's a configurable version that replaces the hard-coded `trackingProfile` from before. Inactive states are always `.off` and deliberately not configurable, so no setting can turn background location on outside a delivery.

```swift
import CoreLocation

// MARK: - Accuracy levels (Codable so they can come from remote config)

enum AccuracyLevel: String, Codable, CaseIterable, Comparable {
    case threeKilometers, kilometer, hundredMeters, tenMeters, best

    var clAccuracy: CLLocationAccuracy {
        switch self {
        case .threeKilometers: return kCLLocationAccuracyThreeKilometers
        case .kilometer:       return kCLLocationAccuracyKilometer
        case .hundredMeters:   return kCLLocationAccuracyHundredMeters
        case .tenMeters:       return kCLLocationAccuracyNearestTenMeters
        case .best:            return kCLLocationAccuracyBest
        }
    }

    private var rank: Int { Self.allCases.firstIndex(of: self)! }
    static func < (l: Self, r: Self) -> Bool { l.rank < r.rank }
}

enum ActivityKind: String, Codable {
    case automotive, otherNavigation, fitness, other

    var clType: CLActivityType {
        switch self {
        case .automotive:      return .automotiveNavigation
        case .otherNavigation: return .otherNavigation
        case .fitness:         return .fitness
        case .other:           return .other
        }
    }
}

// MARK: - Per-state setting

struct StateTracking: Codable, Equatable {
    var accuracy: AccuracyLevel
    var distanceFilter: CLLocationDistance   // meters; use kCLDistanceFilterNone for all movement
    var activity: ActivityKind
}

// MARK: - Settings: one entry per active state

struct LocationTrackingSettings: Codable, Equatable {
    var headingToPickup: StateTracking
    var atPickup: StateTracking
    var headingToDropoff: StateTracking
    var atDropoff: StateTracking

    /// Conservative starting point. Tune after measuring (see notes below).
    static let `default` = LocationTrackingSettings(
        headingToPickup:  .init(accuracy: .hundredMeters, distanceFilter: 100, activity: .automotive),
        atPickup:         .init(accuracy: .hundredMeters, distanceFilter: 100, activity: .otherNavigation),
        headingToDropoff: .init(accuracy: .tenMeters,     distanceFilter: 25,  activity: .automotive),
        atDropoff:        .init(accuracy: .tenMeters,     distanceFilter: 10,  activity: .otherNavigation)
    )

    func profile(for state: DeliveryState) -> LocationTrackingProfile {
        let s: StateTracking
        switch state {
        case .idle, .completed, .cancelled: return .off   // not configurable by design
        case .headingToPickup:  s = headingToPickup
        case .atPickup:         s = atPickup
        case .headingToDropoff: s = headingToDropoff
        case .atDropoff:        s = atDropoff
        }
        return .active(accuracy: s.accuracy.clAccuracy,
                       distanceFilter: s.distanceFilter,
                       activity: s.activity.clType)
    }
}
```

## Loading the settings

This lets you ship defaults and adjust them remotely without an app release. Fall back to the defaults if the remote payload is missing or malformed.

```swift
final class LocationSettingsProvider {
    private(set) var current: LocationTrackingSettings

    init(remote: Data? = nil) {
        if let remote,
           let decoded = try? JSONDecoder().decode(LocationTrackingSettings.self, from: remote) {
            current = decoded
        } else {
            current = .default
        }
    }

    func profile(for state: DeliveryState) -> LocationTrackingProfile {
        current.profile(for: state)
    }
}
```

## Applying a profile to the manager

```swift
extension CLLocationManager {
    func apply(_ profile: LocationTrackingProfile) {
        switch profile {
        case .off:
            stopUpdatingLocation()
            allowsBackgroundLocationUpdates = false

        case let .active(accuracy, filter, activity):
            desiredAccuracy = accuracy
            distanceFilter = filter
            activityType = activity
            // Auto-pausing can stop updates at a red light or while the courier
            // is inside a restaurant, which would break the live map.
            pausesLocationUpdatesAutomatically = false
            allowsBackgroundLocationUpdates = true
            startUpdatingLocation()
        }
    }
}

