Here's a helper built around `CAFrameRateRange` (iOS 15+) with fallbacks for older versions where possible.

```swift
import UIKit
import QuartzCore
import MetalKit

/// Caps the frame rate of animations and display links.
struct FrameRateCap {
    let maxFPS: Int

    static let standard = FrameRateCap(maxFPS: 60)
    static let saver    = FrameRateCap(maxFPS: 30)

    /// Drops to 30 fps in Low Power Mode, otherwise 60.
    static var adaptive: FrameRateCap {
        ProcessInfo.processInfo.isLowPowerModeEnabled ? .saver : .standard
    }

    @available(iOS 15.0, *)
    var range: CAFrameRateRange {
        let fps = Float(maxFPS)
        return CAFrameRateRange(minimum: fps / 2, maximum: fps, preferred: fps)
    }

    // MARK: - Apply

    /// For custom per-frame drawing/animation loops.
    func apply(to link: CADisplayLink) {
        if #available(iOS 15.0, *) {
            link.preferredFrameRateRange = range
        } else {
            link.preferredFramesPerSecond = maxFPS
        }
    }

    /// For Core Animation animations (CABasicAnimation, CAKeyframeAnimation, etc.).
    /// No-op before iOS 15, as there's no per-animation API.
    func apply(to animation: CAAnimation) {
        if #available(iOS 15.0, *) {
            animation.preferredFrameRateRange = range
        }
    }

    /// For Metal-backed views (maps, custom rendering).
    func apply(to view: MTKView) {
        view.preferredFramesPerSecond = maxFPS
    }

    /// Convenience: creates a display link that is already capped.
    func makeDisplayLink(target: Any, selector: Selector) -> CADisplayLink {
        let link = CADisplayLink(target: target, selector: selector)
        apply(to: link)
        return link
    }
}
```

Usage:

```swift
// Display link
let link = FrameRateCap.adaptive.makeDisplayLink(target: self, selector: #selector(tick))
link.add(to: .main, forMode: .common)

// Core Animation
let anim = CABasicAnimation(keyPath: "position.y")
anim.toValue = 200
anim.duration = 0.4
FrameRateCap.saver.apply(to: anim)
layer.add(anim, forKey: "move")
```

To react when the user toggles Low Power Mode, observe `Notification.Name.NSProcessInfoPowerStateDidChange` and re-apply `FrameRateCap.adaptive` to your active display links.

A few caveats:
- **It's a hint.** The system may still choose a different rate, though in practice it respects the maximum.
- **Coverage is partial.** This doesn't affect plain `UIView.animate` or SwiftUI's built-in animations, which run at the system's rate. It only covers display links, `CAAnimation`s, and Metal views.
- **Measure the effect.** Profile with Instruments (Energy Log, Time Profiler) before and after. In delivery apps, the biggest battery drains are usually continuous location updates, polling or chatty networking, and map rendering. If the capped animations aren't a major cost, you may see little improvement.
- **Dark theme only saves power on OLED iPhones**, and mainly when the UI is mostly dark pixels. It's a good feature, but it may not noticeably change the battery complaints.

