  const priorCount = await countActiveConnections(ctx.accountId);

  analytics.track({
    event: "data_source_connected",
    event_id: `${conn.id}:connected`,
    timestamp: new Date().toISOString(),
    user_id: ctx.userId,
    account_id: ctx.accountId,
