export interface Connector {
  id: string;
  name: string;
  category: string;
  logo_url: string;
  auth_type: "oauth2" | "credentials" | "api_key";
  popularity_rank?: number;
}

interface ListResponse {
  data: Connector[];
  next_cursor: string | null;
}

export async function listConnectors(token: string): Promise<Connector[]> {
  const connectors: Connector[] = [];
  let cursor: string | null = null;

  do {
    const url = new URL("https://api.yourapp.com/v1/connectors");
    url.searchParams.set("status", "available");
    url.searchParams.set("limit", "50");
    if (cursor) url.searchParams.set("cursor", cursor);

    const res = await fetch(url, {
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/json",
      },
    });

    if (!res.ok) {
      throw new Error(`Failed to list connectors: ${res.status} ${res.statusText}`);
    }

    const body: ListResponse = await res.json();
    connectors.push(...body.data);
    cursor = body.next_cursor;
  } while (cursor);

  return connectors;
}
```

