## `totp-crypto.js`: encrypt secrets at rest

TOTP secrets must be recoverable to verify codes, so you can't hash them like passwords. Encrypt them instead.

```js
import crypto from "node:crypto";

// 32 random bytes, base64-encoded. Keep it in a secrets manager / env var, not in the DB.
const KEY = Buffer.from(process.env.MFA_ENCRYPTION_KEY, "base64");
if (KEY.length !== 32) throw new Error("MFA_ENCRYPTION_KEY must be 32 bytes (base64)");

export function encryptSecret(plaintext) {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv("aes-256-gcm", KEY, iv);
  const ct = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([iv, tag, ct]).toString("base64");
}

export function decryptSecret(payload) {
  const buf = Buffer.from(payload, "base64");
  const iv = buf.subarray(0, 12);
  const tag = buf.subarray(12, 28);
  const ct = buf.subarray(28);
  const decipher = crypto.createDecipheriv("aes-256-gcm", KEY, iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ct), decipher.final()]).toString("utf8");
}
```

