import QRCode from "qrcode";
import { encryptSecret } from "./totp-crypto.js";

const router = express.Router();

const ISSUER = "YourCompany Admin"; // shown in the authenticator app

const setupLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  standardHeaders: true,
  legacyHeaders: false,
});

// Assumes you already have:
//   requireAuth   - validates the session and sets req.user
//   requireAdmin  - checks req.user has an admin role
//   mfaStore      - your persistence layer (replace with your ORM calls)
router.post(
  "/api/admin/mfa/totp/setup",
  requireAuth,
  requireAdmin,
  setupLimiter,
  async (req, res, next) => {
    try {
      const user = req.user;

      const existing = await mfaStore.get(user.id);
      if (existing?.enabled) {
        // Don't let a (possibly hijacked) session silently replace an active factor.
        // Require a separate, re-authenticated "reset" flow instead.
        return res.status(409).json({ error: "TOTP is already enabled for this account." });
      }

      const secret = authenticator.generateSecret(20); // 160-bit, base32
      const otpauthUrl = authenticator.keyuri(user.email, ISSUER, secret);
      const qrCodeDataUrl = await QRCode.toDataURL(otpauthUrl, {
        errorCorrectionLevel: "M",
        margin: 2,
        width: 256,
      });

      // Store as PENDING. Overwrites any previous unconfirmed enrollment.
      await mfaStore.upsert(user.id, {
        secretEncrypted: encryptSecret(secret),
        enabled: false,
        createdAt: new Date(),
        confirmedAt: null,
      });

      await auditLog.write({
        actor: user.id,
        action: "mfa.totp.setup_initiated",
        ip: req.ip,
      });

      res.set("Cache-Control", "no-store");
      res.status(200).json({
        qrCodeDataUrl,       // render in <img src="...">
        manualEntryKey: secret, // fallback if the user can't scan
      });
    } catch (err) {
      next(err);
    }
  }
);

export default router;
```

## Design notes

- **Pending until verified.** The secret isn't active (`enabled: false`) until the user proves their app works by submitting a valid code. That's the next endpoint. Without it, a typo or failed scan could lock an admin out.
- **No re-enrollment over an active factor.** If TOTP is already enabled, setup returns 409. Resetting should require re-authentication or a second admin's approval.
- **Secret exposure is minimal.** It's returned only in this one response (with `no-store`), never logged, and stored encrypted. Make sure your request/response logging and APM tools don't capture this response body.
- **Audit logging.** SOC 2 auditors like to see MFA lifecycle events (setup, confirm, disable, reset, failed verifications).

## What's still needed for the audit

1. **`POST /mfa/totp/verify-setup`** confirms the first code, sets `enabled: true`, and generates recovery codes (stored hashed, shown once).
2. **Login enforcement.** The login flow must require a TOTP code for admins, with rate limiting/lockout on attempts and replay protection (reject a code reused within its time step).
3. **Recovery codes and a reset process.** Admins will lose phones, and the reset path is a common audit finding if it's weak.
4. **Enforcement and evidence.** Block admin access until MFA is enrolled, and be able to produce a report showing 100% of admin accounts have it enabled.

