```js
import crypto from "node:crypto";

const PEPPER = Buffer.from(process.env.MFA_RECOVERY_PEPPER || "", "base64");
if (PEPPER.length !== 32) throw new Error("MFA_RECOVERY_PEPPER must be 32 bytes (base64)");

// 32 symbols, so (byte & 31) maps uniformly with no modulo bias.
// Excludes 0/O and 1/I to avoid misreading when typed from a printout.
const ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
const CODE_COUNT = 10;
const CODE_LENGTH = 10; // 10 chars x 5 bits = 50 bits of entropy per code

function randomCode() {
  const bytes = crypto.randomBytes(CODE_LENGTH);
  let raw = "";
  for (const b of bytes) raw += ALPHABET[b & 31];
  return `${raw.slice(0, 5)}-${raw.slice(5)}`; // display format: XXXXX-XXXXX
}

// Accepts user input like "abcde 23456" or "ABCDE-23456".
export function normalizeCode(input) {
  return String(input).toUpperCase().replace(/[^A-Z0-9]/g, "");
}

// HMAC with a server-side pepper (not a bare hash). The codes are random, so a slow
// hash like bcrypt isn't needed, but 50 bits is brute-forceable offline if the DB
// leaks and the hash is unkeyed. The pepper lives in your secrets manager, not the DB.
export function hashCode(code) {
  return crypto.createHmac("sha256", PEPPER).update(normalizeCode(code)).digest("hex");
}

export function generateRecoveryCodes() {
  const codes = Array.from({ length: CODE_COUNT }, randomCode);
  return { codes, hashes: codes.map(hashCode) };
}

/**
 * Generate a fresh set, atomically replacing any existing set.
 * Returns plaintext codes, which the caller must show once and never persist.
 */
export async function issueRecoveryCodes(userId, mfaStore) {
  const { codes, hashes } = generateRecoveryCodes();
  await mfaStore.replaceRecoveryCodes(userId, hashes); // delete old + insert new in ONE transaction
  return codes;
}

/**
 * Attempt to use a recovery code during login.
 * Returns { ok, remaining }.
 */
export async function consumeRecoveryCode(userId, input, mfaStore) {
  const normalized = normalizeCode(input);
  if (normalized.length !== CODE_LENGTH) return { ok: false, remaining: null };

  // Must be an atomic compare-and-set, e.g.:
  //   UPDATE recovery_codes SET used_at = now()
  //   WHERE user_id = $1 AND code_hash = $2 AND used_at IS NULL
  // and return true only if rowCount === 1. A read-then-write lets two concurrent
  // requests spend the same code.
  const ok = await mfaStore.consumeRecoveryCode(userId, hashCode(normalized));
  if (!ok) return { ok: false, remaining: null };

  const remaining = await mfaStore.countUnusedRecoveryCodes(userId);
  return { ok: true, remaining };
}
```

## Suggested schema

```sql
CREATE TABLE mfa_recovery_codes (
  id         BIGSERIAL PRIMARY KEY,
  user_id    BIGINT NOT NULL REFERENCES users(id),
  code_hash  CHAR(64) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  used_at    TIMESTAMPTZ,
  UNIQUE (user_id, code_hash)
);
CREATE INDEX ON mfa_recovery_codes (user_id) WHERE used_at IS NULL;
```

Keeping used rows (rather than deleting them) gives you an audit trail.

