  FROM invoices i
  LEFT JOIN invoice_line_items li ON li.invoice_id = i.id
  WHERE i.customer_id = $1
  ORDER BY i.issued_at DESC, i.id, li.id
`;

const COLUMNS = [
  { key: 'invoice_number', header: 'Invoice Number' },
  { key: 'issued_at',      header: 'Issued' },
  { key: 'due_at',         header: 'Due' },
  { key: 'status',         header: 'Status' },
  { key: 'currency',       header: 'Currency' },
  { key: 'description',    header: 'Description' },
  { key: 'quantity',       header: 'Quantity' },
  { key: 'unit_price',     header: 'Unit Price' },
  { key: 'line_amount',    header: 'Line Amount' },
  { key: 'invoice_total',  header: 'Invoice Total' },
];

// Assumes money is stored as integer cents. Remove if you use numeric columns.
const money = (cents) => (cents == null ? '' : (Number(cents) / 100).toFixed(2));
const isoDate = (d) => (d ? d.toISOString().slice(0, 10) : '');

// Prevent spreadsheet formula injection in free-text fields.
const safeText = (s) =>
  typeof s === 'string' && /^[=+\-@\t\r]/.test(s) ? `'${s}` : s ?? '';

const toCsvRow = () =>
  new Transform({
    objectMode: true,
    transform(r, _enc, cb) {
      cb(null, {
        invoice_number: safeText(r.invoice_number),
        issued_at:      isoDate(r.issued_at),
        due_at:         isoDate(r.due_at),
        status:         r.status,
        currency:       r.currency,
        description:    safeText(r.description),
        quantity:       r.quantity ?? '',
        unit_price:     money(r.unit_price),
        line_amount:    money(r.line_amount),
        invoice_total:  money(r.invoice_total),
      });
    },
  });

router.get('/billing/invoices.csv', requireAuth, async (req, res, next) => {
  const customerId = req.user.customerId; // from the session, never from the request
  const client = await pool.connect();
  let failure;

  try {
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader(
      'Content-Disposition',
      `attachment; filename="invoices-${new Date().toISOString().slice(0, 10)}.csv"`
    );
    res.setHeader('Cache-Control', 'no-store');

    await pipeline(
      client.query(new QueryStream(INVOICE_CSV_SQL, [customerId])),
      toCsvRow(),
      stringify({ header: true, columns: COLUMNS, bom: true }),
      res
    );
  } catch (err) {
    failure = err;
    if (!res.headersSent) {
      res.removeHeader('Content-Disposition');
      next(err); // nothing sent yet, so a normal error response works
    } else {
      res.destroy(err); // abort so the browser sees a failed download, not a truncated "complete" file
    }
  } finally {
    client.release(failure); // passing an error makes the pool discard this connection
  }
});
```

**Notes on the choices**

- **`pipeline` handles backpressure and cleanup.** If the user cancels the download, it destroys the query stream, which closes the cursor. The `finally` block then returns the connection to the pool.
- **Mid-stream failures.** Once the first bytes are sent, you can't change the status code. Destroying the response makes the download fail visibly, which is better than handing the customer a silently incomplete invoice history.
- **Formula injection.** `safeText` prefixes a `'` to text starting with `=`, `+`, `-`, or `@`, so a malicious description can't execute as a formula in Excel. It's applied only to text fields, not money, so negative amounts like credits stay numeric.
- **`bom: true`** adds a UTF-8 byte-order mark so Excel reads non-ASCII characters correctly. Drop it if your customers mostly use other tools.
- **Dates** are `YYYY-MM-DD`, which sorts and parses reliably. Use full ISO timestamps if time of day matters.
- **Connection use.** A streaming request holds a pooled connection for the entire download, so a slow client ties one up. Consider a `statement_timeout`, a rate limit on this route, or both.

**For the button:** use a plain `<a href="/billing/invoices.csv" download>`. Don't use `fetch()` and a Blob, because that buffers the whole file in browser memory and the session cookie already handles auth.

