```ts
import { createHmac, timingSafeEqual } from "node:crypto";
import type { Pool } from "pg";

const SECRET = process.env.INVITE_SIGNING_SECRET;
if (!SECRET || SECRET.length < 32) {
  throw new Error("INVITE_SIGNING_SECRET must be set (32+ chars)");
}
const APP_URL = process.env.APP_URL ?? "http://localhost:3000";

export class InviteError extends Error {
  constructor(public code: "already_member") {
    super(code);
  }
}

// ---- signing / verification ----

function hmac(data: string): Buffer {
  return createHmac("sha256", SECRET!).update(data).digest();
}

export function signInviteToken(inviteId: string, expiresAt: Date): string {
  const payload = Buffer.from(
    JSON.stringify({ i: inviteId, exp: Math.floor(expiresAt.getTime() / 1000) })
  ).toString("base64url");
  return `${payload}.${hmac(payload).toString("base64url")}`;
}

/** Returns the invite id if the signature is valid and the token hasn't expired. */
export function verifyInviteToken(token: string): { inviteId: string } | null {
  const parts = token.split(".");
  if (parts.length !== 2) return null;
  const [payload, sig] = parts;

  const expected = hmac(payload);
  const given = Buffer.from(sig, "base64url");
  if (given.length !== expected.length || !timingSafeEqual(given, expected)) {
    return null;
  }

  let claims: { i?: unknown; exp?: unknown };
  try {
    claims = JSON.parse(Buffer.from(payload, "base64url").toString("utf8"));
  } catch {
    return null;
  }
  if (typeof claims.i !== "string" || typeof claims.exp !== "number") return null;
  if (claims.exp * 1000 <= Date.now()) return null;

  return { inviteId: claims.i };
}

// ---- creating an invite ----

export async function createTeamInvite(
  db: Pool,
  args: { teamId: string; email: string; invitedBy: string; role?: string }
): Promise<{ inviteId: string; link: string; expiresAt: Date }> {
  const email = args.email.trim();
  const role = args.role ?? "member";

  const client = await db.connect();
  try {
    await client.query("BEGIN");

    // Don't invite someone who's already on the team
    const member = await client.query(
      `SELECT 1
         FROM team_members tm
         JOIN users u ON u.id = tm.user_id
        WHERE tm.team_id = $1 AND u.email = $2`,
      [args.teamId, email]
    );
    if (member.rowCount) throw new InviteError("already_member");

    // Supersede any earlier open invite (including expired-but-unaccepted ones),
    // so the unique index doesn't block re-inviting or resending
    await client.query(
      `UPDATE team_invites
          SET revoked_at = now()
        WHERE team_id = $1 AND email = $2
          AND accepted_at IS NULL AND revoked_at IS NULL`,
      [args.teamId, email]
    );

    const { rows } = await client.query<{ id: string; expires_at: Date }>(
      `INSERT INTO team_invites (team_id, email, role, invited_by)
       VALUES ($1, $2, $3, $4)
       RETURNING id, expires_at`,
      [args.teamId, email, role, args.invitedBy]
    );

    await client.query("COMMIT");

    const { id, expires_at } = rows[0];
    const token = signInviteToken(id, expires_at);
    return {
      inviteId: id,
      link: `${APP_URL}/invites/accept?token=${encodeURIComponent(token)}`,
      expiresAt: expires_at,
    };
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}
```

**Notes**
- **Expiry comes from the row.** The token's `exp` is copied from `expires_at`, so the two can't disagree. The accept query still checks `expires_at > now()` and `revoked_at IS NULL`, because a valid signature doesn't mean the invite is still live.
- **The token is signed, not encrypted.** Anyone holding it can read the invite id and expiry, which is harmless since it's just a uuid. Don't put the email or team name in the payload unless you're fine with that.
- **Authorization isn't checked here.** The endpoint calling this must confirm that `invitedBy` is an owner of `teamId`. I left it out because I don't know how you model ownership.
- **Concurrent invites:** if two requests invite the same email at the same moment, the partial unique index makes one of them fail with Postgres error `23505`. You can catch that and return a 409, or retry.
- **Sending the email** is separate. Pass `link` to whatever mailer you use, and send it after the commit, as above, so you never email a link for an invite that didn't persist.
- **Secret rotation:** if you ever need to rotate `INVITE_SIGNING_SECRET`, all outstanding links will break. Since the rows are the source of truth, you can just resend them.

